export const getPetSuppliesProducts = (): Product[] => PET_SUPPLIES_PRODUCTS;

export const getFeaturedPetSuppliesProducts = (): Product[] => 
  PET_SUPPLIES_PRODUCTS.filter(product => product.featured);

export const getPetSuppliesProductsByBadge = (badge: string): Product[] =>
  PET_SUPPLIES_PRODUCTS.filter(product => product.badge === badge);

export const getPetSuppliesProductsByPriceRange = (min: number, max: number): Product[] =>
  PET_SUPPLIES_PRODUCTS.filter(product => product.price >= min && product.price <= max);
